mapper.select:
SELECT id, user_id, plan_id, content_id, training_date, status,
       scheduled_at, completed_at, created_at, updated_at
FROM training_task WHERE id = #{taskId}

mapper.update:
UPDATE training_task
SET status = #{newStatus}, completed_at = #{completedAt}, updated_at = CURRENT_TIMESTAMP
WHERE id = #{taskId} AND status = #{expectedStatus}

UPDATE training_task
SET content_id = #{contentId}, updated_at = CURRENT_TIMESTAMP
WHERE id = #{taskId} AND status = #{expectedStatus}
